import {
    Address,
    CheckoutRequestBody,
    CheckoutSelectors,
    Country,
    Customer,
    FormField,
} from '@bigcommerce/checkout-sdk';
import { noop } from 'lodash';
import React, { Component, ReactNode } from 'react';
import { connect } from 'react-redux'

import B3Checkout from '../b3checkout'
import { TranslatedString } from '@bigcommerce/checkout/locale';
import { CheckoutContextProps } from '@bigcommerce/checkout/payment-integration-api';
import { AddressFormSkeleton } from '@bigcommerce/checkout/ui';

import { isEqualAddress, mapAddressFromFormValues } from '../address';
import { withCheckout } from '../checkout';
import { EMPTY_ARRAY, isFloatingLabelEnabled } from '../common/utility';
import { getShippableItemsCount } from '../shipping';
import { Legend } from '../ui/form';

import BillingForm, { BillingFormValues } from './BillingForm';
import CheckoutStepType from '../checkout/CheckoutStepType';
import {  NoAddressTip } from '../b3checkout'
import getBillingMethodId from './getBillingMethodId';

export interface BillingProps {
    navigateNextStep(): void;
    onReady?(): void;
    onUnhandledError(error: Error): void;
    type: CheckoutStepType
}

export interface WithCheckoutBillingProps {
    countries: Country[];
    countriesWithAutocomplete: string[];
    customer: Customer;
    customerMessage: string;
    googleMapsApiKey: string;
    isInitializing: boolean;
    isUpdating: boolean;
    shouldShowOrderComments: boolean;
    billingAddress?: Address;
    methodId?: string;
    isFloatingLabelEnabled?: boolean;
    getFields(countryCode?: string): FormField[];
    initialize(): Promise<CheckoutSelectors>;
    updateAddress(address: Partial<Address>): Promise<CheckoutSelectors>;
    updateCheckout(payload: CheckoutRequestBody): Promise<CheckoutSelectors>;
}

interface B3Props {
    isB3User: boolean
    b3Company: any
    checkoutSettings: any
}

class Billing extends Component<B3Props & BillingProps & WithCheckoutBillingProps> {
    async componentDidMount(): Promise<void> {
        const { initialize, onReady = noop, onUnhandledError } = this.props;

        try {
            await initialize();
            onReady();
        } catch (error) {
            if (error instanceof Error) {
                onUnhandledError(error);
            }
        }
    }

    get shouldAllowNewAddress() {
        const { checkoutSettings } = this.props

        return checkoutSettings['billing.address.add']
    }

    get addresses() {
        const {
            customer,
            isB3User,
            b3Company,
        } = this.props

        return isB3User
            ? b3Company.addresses.filter((address: { isBilling: number }) => address.isBilling === 1)
            : customer.addresses
    }

    render(): ReactNode {
        const {
            updateAddress,
            isInitializing,
            type,
            isB3User,
            ...props
        } = this.props;

        const isShouldShowNewAddressForm = !(isB3User ? !this.addresses.length && !this.shouldAllowNewAddress : false)

        return (
            <AddressFormSkeleton isLoading={isInitializing}>
                <div className="checkout-form">
                    {
                        isShouldShowNewAddressForm  ? (
                            <>
                                <div className="form-legend-container">
                                    <Legend testId="billing-address-heading">
                                        <TranslatedString id="billing.billing_address_heading" />
                                    </Legend>
                                </div>
                                <BillingForm
                                    {...props}
                                    onSubmit={this.handleSubmit}
                                    type={ type }
                                    updateAddress={updateAddress}
                                />
                            </>
                        ) : (<NoAddressTip type="billing" />)
                    }
                    
                </div>
            </AddressFormSkeleton>
        );
    }

    private handleSubmit: (values: BillingFormValues) => void = async ({
        orderComment,
        ...addressValues
    }) => {
        const {
            updateAddress,
            updateCheckout,
            customerMessage,
            billingAddress,
            navigateNextStep,
            onUnhandledError,
            isB3User,
            b3Company,
            getFields,
            checkoutSettings,
        } = this.props;

        const promises: Array<Promise<CheckoutSelectors>> = [];
        let address = mapAddressFromFormValues(addressValues);

        // Fix masquerading issue: When super admin is masquerading, prevent using super admin's personal address
        // but allow selecting company addresses or entering new addresses
        const isMasquerading = isB3User && B3Checkout?.store?.getState &&
            (B3Checkout.store.getState()?.global?.selectCompanyHierarchyId > 0 || 
             (typeof sessionStorage !== 'undefined' && sessionStorage.getItem('sf-isAgenting') === 'true') ||
             (B3Checkout.utils?.storage?.B3RoleId?.getValue && 
              B3Checkout.utils?.constants?.B3Role?.SALESREP && 
              B3Checkout.utils.storage.B3RoleId.getValue() === B3Checkout.utils.constants.B3Role.SALESREP))
        
        if (isMasquerading && isB3User && b3Company) {
            // When masquerading, check if the address is a valid company billing address or new address
            // Only override if it's the super admin's personal address
            const addressWithId = address as any
            const hasAddressId = addressWithId?.addressId && String(addressWithId.addressId).trim() !== ''
            const isCompanyAddress = hasAddressId && b3Company.addresses?.some(
                (addr: any) => addr.isBilling === 1 && 
                String(addr.addressId) === String(addressWithId.addressId)
            )
            
            // Only override if address has an ID that's NOT in company addresses (i.e., super admin's personal address)
            // Don't override if: (1) it's a company address, or (2) it's a new address (no ID)
            if (hasAddressId && !isCompanyAddress) {
                const companyAddress = b3Company.defaultBillingAddress?.address1 
                    ? b3Company.defaultBillingAddress
                    : b3Company.addresses?.find((addr: any) => addr.isBilling === 1)
                
                if (companyAddress && companyAddress.address1) {
                    address = companyAddress
                }
            }
        }

        if (isB3User && (addressValues as any)?.b2bCustomFields) {
            B3Checkout.extrasFiles.saveExtrasAddress((addressValues as any)?.b2bCustomFields, 'billing')
        }
        if (isB3User && checkoutSettings['billing.address.save'] && address?.shouldSaveAddress) {
            try {
                const formFields = getFields(address?.countryCode)
                const isValid = B3Checkout.utils.util.validateAddress(address as Address, b3Company.addresses, formFields)
                sessionStorage.setItem('b3_pending_billing_address', JSON.stringify({
                    newAddress: {
                        ...address,
                        addressId: isValid ? undefined : '',
                    },
                    isBillingMode: true,
                    checkoutSettings,
                    b2bCustomFields: B3Checkout.extrasFiles.decodeAddressExtraFieldsKeys((addressValues as any)?.b2bCustomFields)
                }));
            } catch (error) {
                console.warn('Billing address will not be saved to address book');
            }
        }

        if (address && !isEqualAddress(address, billingAddress)) {
            promises.push(updateAddress(B3Checkout.utils.address.addressFieldOptimize(address)));
        }

        if (customerMessage !== orderComment) {
            promises.push(updateCheckout({ customerMessage: orderComment }));
        }

        try {
            await Promise.all(promises);

            navigateNextStep();
        } catch (error) {
            if (error instanceof Error) {
                onUnhandledError(error);
            }
        }
    };
}

function mapToBillingProps({
    checkoutService,
    checkoutState,
}: CheckoutContextProps): WithCheckoutBillingProps | null {
    const {
        data: {
            getCheckout,
            getConfig,
            getCart,
            getCustomer,
            getBillingAddress,
            getBillingAddressFields,
            getBillingCountries,
        },
        statuses: { isLoadingBillingCountries, isUpdatingBillingAddress, isUpdatingCheckout },
    } = checkoutState;

    const config = getConfig();
    const customer = getCustomer();
    const checkout = getCheckout();
    const cart = getCart();

    if (!config || !customer || !checkout || !cart) {
        return null;
    }

    const { enableOrderComments, googleMapsApiKey } = config.checkoutSettings;

    const countriesWithAutocomplete = ['US', 'CA', 'AU', 'NZ', 'GB'];

    return {
        billingAddress: getBillingAddress(),
        countries: getBillingCountries() || EMPTY_ARRAY,
        countriesWithAutocomplete,
        customer,
        customerMessage: checkout.customerMessage,
        getFields: getBillingAddressFields,
        googleMapsApiKey,
        initialize: checkoutService.loadBillingAddressFields,
        isInitializing: isLoadingBillingCountries(),
        isUpdating: isUpdatingBillingAddress() || isUpdatingCheckout(),
        methodId: getBillingMethodId(checkout),
        shouldShowOrderComments: enableOrderComments && getShippableItemsCount(cart) < 1,
        updateAddress: checkoutService.updateBillingAddress,
        updateCheckout: checkoutService.updateCheckout,
        isFloatingLabelEnabled: isFloatingLabelEnabled(config.checkoutSettings),
    };
}

const mapStateToProps = (state: { global: { isB3User: boolean, checkoutSettings: any }, company: any }) => {
    const {
        global: {
            isB3User,
            checkoutSettings,
        },
        company: b3Company,

    } = state

    return {
        isB3User,
        b3Company,
        checkoutSettings,
    }
}

export default connect(mapStateToProps)(withCheckout(mapToBillingProps)(Billing));
